select null, t.id, 'builtin', 'Which method is considered the reference method for glucose determination?', '["Glucose oxidase","Hexokinase","Folin-Wu","o-Toluidine"]'::jsonb, 1, 'The hexokinase method is the reference method because it is highly specific and less affected by interferences than glucose oxidase. Folin-Wu and o-toluidine are older, less specific methods. Reference: StatPearls, Hexokinase Method (ncbi.nlm.nih.gov/books/NBK587446).', '["Common method, but its peroxidase (Trinder) step is affected by reducing agents like vitamin C.","Reference method: hexokinase + G6PD, measured as NADPH at 340 nm.","Old copper-reduction method; nonspecific, other reducing substances react too.","Old method using a toxic aromatic amine; no longer used."]'::jsonb, 1, 'verified'
