select null, t.id, 'builtin', 'Which formula correctly computes the anion gap (without potassium)?', '["Na⁺ − (Cl⁻ + HCO₃⁻)","(Na⁺ + K⁺) − Cl⁻","Cl⁻ − (Na⁺ + HCO₃⁻)","Na⁺ + Cl⁻ − HCO₃⁻"]'::jsonb, 0, 'Anion gap = Na⁺ − (Cl⁻ + HCO₃⁻). When potassium is included it becomes (Na⁺ + K⁺) − (Cl⁻ + HCO₃⁻). Reference: StatPearls, Biochemistry, Anion Gap (ncbi.nlm.nih.gov/books/NBK539757).', '["Cations minus the main measured anions; usually around 8–12 mmol/L.","Leaves out bicarbonate. The K⁺ version is (Na⁺ + K⁺) − (Cl⁻ + HCO₃⁻).","Reversed: the gap is cations minus anions, so it starts from Na⁺.","Both anions (Cl⁻ and HCO₃⁻) must be subtracted, not one added."]'::jsonb, 2, 'verified'
