select null, t.id, 'builtin', 'The Jaffe reaction for creatinine uses which reagent?', '["Diacetyl monoxime","Alkaline picrate","Phosphotungstic acid","o-Cresolphthalein complexone"]'::jsonb, 1, 'In the Jaffe reaction, creatinine reacts with alkaline picrate to form a red-orange complex. Diacetyl monoxime is for urea, phosphotungstic acid for uric acid, and o-cresolphthalein for calcium. Reference: Peake & Whiting, Measurement of Serum Creatinine, Clin Biochem Rev 2006 (pmc.ncbi.nlm.nih.gov/articles/PMC1784008).', '["Reagent for urea (BUN), not creatinine.","Creatinine + picrate in alkaline solution gives a red-orange complex.","Used for uric acid (reduced to tungsten blue) and to precipitate proteins.","Dye used to measure total calcium."]'::jsonb, 2, 'verified'
