select null, t.id, 'builtin', 'High insulin with LOW C-peptide in a hypoglycemic patient suggests:', '["Insulinoma","Injection of insulin","Sulfonylurea use","Type 2 diabetes"]'::jsonb, 1, 'Taking too much insulin suppresses the pancreas, so C-peptide (made with the body''s own insulin) is low. Insulinoma raises C-peptide. Reference: MedlinePlus Lab Tests, C-Peptide Test (medlineplus.gov/lab-tests/c-peptide-test).', '["The tumor makes its own insulin, so insulin AND C-peptide are both high.","Drug insulin has no C-peptide and suppresses the body’s own insulin release.","Stimulates beta cells, so insulin and C-peptide both rise.","Hypoglycemia is not typical without treatment; C-peptide is usually normal or high."]'::jsonb, 3, 'verified'
