insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The Friedewald formula (mg/dL) is:', '["LDL = TC - HDL - TG/5","LDL = TC + HDL - TG/5","LDL = TC - HDL - TG/2","LDL = TC - VLDL + TG/5"]'::jsonb, 0, 'Friedewald estimates VLDL cholesterol with the fixed factor TG/5 (mg/dL), so LDL = total cholesterol - HDL - TG/5. Reference: Comparative Evaluation of 24 LDL-C Estimation Equations Against Direct Assays (pmc.ncbi.nlm.nih.gov/articles/PMC12468580).', '["TG/5 estimates VLDL-cholesterol; subtract it and HDL from total cholesterol.","HDL must be subtracted, not added.","TG/2.2 is the mmol/L version; in mg/dL use TG/5.","TG/5 is itself the VLDL estimate, and HDL is missing."]'::jsonb, 1, 'verified'
