where owner_id is null and choice_notes is null and choices = '["LDL = TC - HDL - TG/5","LDL = TC + HDL - TG/5","LDL = TC - HDL - TG/2","LDL = TC - VLDL + TG/5"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The Friedewald formula (mg/dL) is:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
