select null, t.id, 'builtin', 'A competitive inhibitor:', '["Competes with the substrate for the active site","Binds only to the enzyme-substrate complex","Permanently destroys the enzyme","Speeds up the reaction"]'::jsonb, 0, 'A competitive inhibitor competes with the substrate for binding at the active site, so adding more substrate can overcome it. Reference: OpenStax Biology 2e, 6.5 Enzymes (openstax.org/books/biology-2e/pages/6-5-enzymes).', '["Looks like the substrate, so more substrate overcomes it: Km rises, Vmax unchanged.","That is uncompetitive inhibition (Km and Vmax both fall).","That is irreversible inhibition.","Activators speed reactions; inhibitors slow them."]'::jsonb, 2, 'verified'
