select null, t.id, 'builtin', 'The Westgard 2-2s rule (two consecutive controls beyond the same 2 SD limit) mainly detects:', '["Random error","Systematic error","Clerical error","No error"]'::jsonb, 1, 'The 2-2s rule is responsive only to systematic error (a shift in the mean), and it is not very sensitive by itself. Reference: Westgard QC, Abuses, Misuses, and In-excuses (westgard.com/lessons/westgard-rules/westgard-rules/lesson73.html).', '["Random error is detected by 1-3s and R-4s.","Two in a row past the same limit means a shift in accuracy.","Control rules do not catch clerical errors.","A violation means the run must be rejected."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CC' and t.name = 'Instrumentation & QC'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The Westgard 2-2s rule (two consecutive controls beyond the same 2 SD limit) mainly detects:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Random error is detected by 1-3s and R-4s.","Two in a row past the same limit means a shift in accuracy.","Control rules do not catch clerical errors.","A violation means the run must be rejected."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Random error","Systematic error","Clerical error","No error"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The Westgard 2-2s rule (two consecutive controls beyond the same 2 SD limit) mainly detects:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The R-4s rule (two controls in a run differ by more than 4 SD) indicates:', '["Systematic error","A shift","A trend","Random error"]'::jsonb, 3, 'R-4s is a rule for random error and should be used only within a run, to tell random error from between-run systematic error. Reference: Westgard QC, Abuses, Misuses, and In-excuses (westgard.com/lessons/westgard-rules/westgard-rules/lesson73.html).', '["Systematic error is detected by 2-2s, 4-1s and 10x.","A sudden change in the mean, caught by 2-2s or 10x.","A gradual drift in one direction, caught by 4-1s or 10x.","A large spread within one run means poor precision."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CC' and t.name = 'Instrumentation & QC'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The R-4s rule (two controls in a run differ by more than 4 SD) indicates:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Systematic error is detected by 2-2s, 4-1s and 10x.","A sudden change in the mean, caught by 2-2s or 10x.","A gradual drift in one direction, caught by 4-1s or 10x.","A large spread within one run means poor precision."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Systematic error","A shift","A trend","Random error"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The R-4s rule (two controls in a run differ by more than 4 SD) indicates:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));

commit;
